private.reference_solution:
var words = (Console.ReadLine() ?? "").Trim().Split(' ');
if (words.Length > 100) Environment.Exit(1);
var order = new List<string>();
var counts = new Dictionary<string, int>();
foreach (var word in words)
{
    if (word.Length == 0 || word.Length > 20) Environment.Exit(1);
    foreach (var character in word)
    {
        if (character < 'a' || character > 'z') Environment.Exit(1);
    }
    if (!counts.TryGetValue(word, out _))
    {
        counts[word] = 0;
        order.Add(word);
    }
    counts[word] += 1;
}
foreach (var word in order)
{
    Console.WriteLine($"word={word} count={counts[word]}");
}
